import {esc} from '../lib/util';
// Each figure is composed for a particular teaching relationship, not an icon tile.
const label=(x:number,y:number,t:string,small=false)=>`<text x="${x}" y="${y}" class="${small?'figure-small':'figure-label'}">${esc(t)}</text>`;
const path=(d:string,c='')=>`<path d="${d}" class="${c}"/>`;
const arrow=(x1:number,y1:number,x2:number,y2:number)=>{const a=Math.atan2(y2-y1,x2-x1),c=Math.cos(a),n=Math.sin(a);return path(`M${x1} ${y1}L${x2} ${y2}M${x2-8*c+5*n} ${y2-8*n-5*c}L${x2} ${y2}L${x2-8*c-5*n} ${y2-8*n+5*c}`,'figure-arrow');};
const sheet=(x:number,y:number,w=75,h=95)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" class="figure-paper"/>${path(`M${x+12} ${y+20}h${w-24}m-${w-24} 13h${w-24}m-${w-24} 13h${w-34}`,'figure-fine')}`;
const person=(x:number,y:number)=>`<circle cx="${x}" cy="${y}" r="11"/>${path(`M${x-18} ${y+43}v-12q0-17 18-17t18 17v12m-18-30v40`,'figure-fine')}`;
