 const parts=v.spec.items||v.spec.nodes||v.spec.rows||[];
 const facts=!key&&parts.length&&!['w1_l5_f21','w2_l2_f13'].includes(id)?`<div class="figure-facts">${parts.map((n:any)=>Array.isArray(n)?`<p><b>${esc(n[0])}</b><span>${esc(n.slice(1).join(' · '))}</span></p>`:`<p><b>${esc(n.label||'')}</b>${n.detail?`<span>${esc(n.detail)}</span>`:''}</p>`).join('')}</div>`:'';
 const claim=key?`<div class="figure-claim"><h2>${esc(key.label)}</h2>${key.detail?`<p>${esc(key.detail)}</p>`:''}</div>`:'';
 return `<figure class="lesson-figure" data-figure="${esc(id)}"><svg viewBox="0 0 360 265" role="img" aria-label="${esc(title)}">${body}</svg>${note?`<figcaption>${esc(note)}</figcaption>`:''}</figure>${claim}${facts}`;
